<section class="container py-5" style="max-width:560px"><div class="card shadow-sm"><div class="card-body p-4"><h1 class="h3 mb-4">Create your account</h1><?php if ($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post" action="/register"><?= csrf_field() ?><div class="mb-3"><label class="form-label">Full name</label><input class="form-control" name="name" required></div><div class="mb-3"><label class="form-label">Email address</label><input class="form-control" type="email" name="email" required></div><div class="mb-3"><label class="form-label">Password</label><input class="form-control" type="password" name="password" minlength="8" required></div><div class="mb-4"><label class="form-label">Confirm password</label><input class="form-control" type="password" name="password_confirmation" minlength="8" required></div><button class="btn btn-primary w-100">Create account</button></form><p class="text-muted small mt-3 mb-0">New accounts are created as students.</p></div></div></section>